import socket, sys, threading, gzip, io, os, time

PORT = int(sys.argv[1])
LOG = sys.argv[2]
log = open(LOG, "ab", buffering=0)

def parse(data):
    head = data.split(b"\r\n\r\n",1)[0]
    lines = head.split(b"\r\n")
    reqline = lines[0].decode("latin1")
    parts = reqline.split(" ")
    path = parts[1] if len(parts)>1 else ""
    hdrs = {}
    for l in lines[1:]:
        if b":" in l:
            k,v = l.split(b":",1)
            hdrs[k.decode("latin1").lower()] = v.strip().decode("latin1")
    return reqline, path, hdrs

def handle(c, addr):
    c.settimeout(5.0)
    data = b""
    try:
        while b"\r\n\r\n" not in data:
            ch = c.recv(65536)
            if not ch: break
            data += ch
    except Exception:
        pass
    if not data:
        c.close(); return
    log.write(b"===CONN from " + str(addr).encode() + b"===\n" + data + b"===END===\n")
    reqline, path, hdrs = parse(data)
    # route on path (may be absolute-URI for proxy)
    p = path
    for pref in ("http://","https://"):
        if p.lower().startswith(pref):
            rest = p[len(pref):]
            i = rest.find("/")
            p = rest[i:] if i>=0 else "/"
    def send(status, headers, body, close=True, http="HTTP/1.1"):
        out = ("%s %s\r\n" % (http, status)).encode()
        for k,v in headers:
            out += ("%s: %s\r\n" % (k,v)).encode()
        if close:
            out += b"Connection: close\r\n"
        out += b"\r\n"
        if body is not None:
            out += body
        try: c.sendall(out)
        except Exception: pass

    J = b'{"a":1,"b":"hi"}'
    if p == "/ok.json":
        send("200 OK", [("Content-Type","application/json"),("Content-Length",str(len(J)))], J)
    elif p == "/plain":
        send("200 OK", [("Content-Type","text/plain"),("Content-Length",str(len(J)))], J)
    elif p == "/noct":
        out = b"HTTP/1.1 200 OK\r\nContent-Length: "+str(len(J)).encode()+b"\r\nConnection: close\r\n\r\n"+J
        try: c.sendall(out)
        except Exception: pass
    elif p == "/html":
        send("200 OK", [("Content-Type","text/html; charset=utf-8"),("Content-Length",str(len(J)))], J)
    elif p == "/octet":
        send("200 OK", [("Content-Type","application/octet-stream"),("Content-Length",str(len(J)))], J)
    elif p == "/204":
        send("204 No Content", [], b"")
    elif p == "/204body":
        # illegal but test
        send("204 No Content", [("Content-Type","application/json"),("Content-Length",str(len(J)))], J)
    elif p == "/400":
        send("400 Bad Request", [("Content-Type","application/json"),("Content-Length",str(len(J)))], J)
    elif p == "/404":
        send("404 Not Found", [("Content-Type","application/json"),("Content-Length",str(len(J)))], J)
    elif p == "/500":
        send("500 Internal Server Error", [("Content-Type","application/json"),("Content-Length",str(len(J)))], J)
    elif p == "/403nonjson":
        b = b"<html>nope</html>"
        send("403 Forbidden", [("Content-Type","text/html"),("Content-Length",str(len(b)))], b)
    elif p == "/301":
        send("301 Moved Permanently", [("Location","/ok.json"),("Content-Length","0")], b"")
    elif p == "/302":
        send("302 Found", [("Location","/ok.json"),("Content-Length","0")], b"")
    elif p == "/303":
        send("303 See Other", [("Location","/ok.json"),("Content-Length","0")], b"")
    elif p == "/307":
        send("307 Temporary Redirect", [("Location","/ok.json"),("Content-Length","0")], b"")
    elif p == "/308":
        send("308 Permanent Redirect", [("Location","/ok.json"),("Content-Length","0")], b"")
    elif p.startswith("/hop"):
        n = int(p[4:] or "0")
        send("302 Found", [("Location","/hop%d" % (n+1)),("Content-Length","0")], b"")
    elif p == "/loop":
        send("302 Found", [("Location","/loop"),("Content-Length","0")], b"")
    elif p == "/relnoloc":
        send("302 Found", [("Content-Length","0")], b"")
    elif p == "/gzip":
        buf = io.BytesIO()
        with gzip.GzipFile(fileobj=buf, mode="wb") as f: f.write(J)
        gz = buf.getvalue()
        send("200 OK", [("Content-Type","application/json"),("Content-Encoding","gzip"),("Content-Length",str(len(gz)))], gz)
    elif p == "/deflate":
        import zlib
        d = zlib.compress(J)
        send("200 OK", [("Content-Type","application/json"),("Content-Encoding","deflate"),("Content-Length",str(len(d)))], d)
    elif p == "/chunked":
        out = b"HTTP/1.1 200 OK\r\nContent-Type: application/json\r\nTransfer-Encoding: chunked\r\nConnection: close\r\n\r\n"
        out += b"8\r\n{\"a\":1,\"\r\n"
        out += b"8\r\nb\":\"hi\"}\r\n"
        out += b"0\r\n\r\n"
        try: c.sendall(out)
        except Exception: pass
    elif p == "/empty":
        send("200 OK", [("Content-Type","application/json"),("Content-Length","0")], b"")
    elif p == "/badjson":
        b = b"{not json at all"
        send("200 OK", [("Content-Type","application/json"),("Content-Length",str(len(b)))], b)
    elif p == "/big":
        # large JSON array
        n = 200000
        parts = [b'{"i":%d}' % i for i in range(n)]
        b = b"[" + b",".join(parts) + b"]"
        send("200 OK", [("Content-Type","application/json"),("Content-Length",str(len(b)))], b)
    elif p == "/lines":
        b = b'{"a":1}\n{"a":2}\n{"a":3}\n'
        send("200 OK", [("Content-Type","application/json"),("Content-Length",str(len(b)))], b)
    elif p == "/gronlines":
        b = b'json = {};\njson.a = 1;\n'
        send("200 OK", [("Content-Type","text/plain"),("Content-Length",str(len(b)))], b)
    elif p == "/hang":
        time.sleep(120)
    elif p == "/slowheaders":
        time.sleep(30)
        send("200 OK", [("Content-Type","application/json"),("Content-Length",str(len(J)))], J)
    elif p == "/truncated":
        out = b"HTTP/1.1 200 OK\r\nContent-Type: application/json\r\nContent-Length: 100\r\n\r\n" + J
        try: c.sendall(out)
        except Exception: pass
        c.close(); return
    elif p == "/echo":
        import json as _j
        b = _j.dumps({"requestline":reqline,"headers":hdrs}).encode()
        send("200 OK", [("Content-Type","application/json"),("Content-Length",str(len(b)))], b)
    else:
        b = b'{"path":"' + p.encode().replace(b'"',b'') + b'"}'
        send("200 OK", [("Content-Type","application/json"),("Content-Length",str(len(b)))], b)
    time.sleep(0.05)
    try: c.close()
    except Exception: pass

s = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
s.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
s.bind(("0.0.0.0", PORT))
s.listen(50)
sys.stderr.write("listening %d\n" % PORT); sys.stderr.flush()
while True:
    c,a = s.accept()
    threading.Thread(target=handle, args=(c,a), daemon=True).start()
EOF
