import socket, threading, sys, struct
PORT=int(sys.argv[1]); LOG=sys.argv[2]
log=open(LOG,"a",buffering=1)
def pipe(a,b):
    try:
        while True:
            d=a.recv(65536)
            if not d: break
            b.sendall(d)
    except Exception: pass
    try: b.shutdown(socket.SHUT_WR)
    except Exception: pass
def handle(c):
    try:
        v=c.recv(2)
        nm=v[1]; c.recv(nm)
        c.sendall(b"\x05\x00")
        hdr=c.recv(4)
        atyp=hdr[3]
        if atyp==1:
            addr=socket.inet_ntoa(c.recv(4))
        elif atyp==3:
            l=c.recv(1)[0]; addr=c.recv(l).decode()
        else:
            addr=str(c.recv(16))
        port=struct.unpack(">H", c.recv(2))[0]
        log.write("SOCKS5 CONNECT %s:%d\n" % (addr,port))
        # map any host to 127.0.0.1:18080
        try:
            up=socket.create_connection(("127.0.0.1",18080),3)
        except Exception:
            c.sendall(b"\x05\x01\x00\x01"+b"\x00"*6); c.close(); return
        c.sendall(b"\x05\x00\x00\x01"+socket.inet_aton("127.0.0.1")+struct.pack(">H",18080))
        t=threading.Thread(target=pipe,args=(c,up),daemon=True); t.start()
        pipe(up,c)
    except Exception as e:
        log.write("ERR %r\n"%e)
    try: c.close()
    except Exception: pass
s=socket.socket(); s.setsockopt(socket.SOL_SOCKET,socket.SO_REUSEADDR,1)
s.bind(("127.0.0.1",PORT)); s.listen(20)
while True:
    c,a=s.accept(); threading.Thread(target=handle,args=(c,),daemon=True).start()
EOF
